local AloeCultivator = {}
local PRODUCTS = {
    common_aloe_leaf_bunch = { name = "Snop listov aloje", woodCost = 1, clayCost = 1, time = 3, cost = 30, healing = 8, happiness = 1, description = "Snop listov aloje za preproste obloge." },
    fresh_aloe_gel_jar = { name = "Kozarec gela aloje", woodCost = 1, glassCost = 1, clayCost = 1, time = 5, cost = 90, healing = 18, happiness = 1, prestige = 1, description = "Svež gel aloje v steklenem kozarcu." },
    distilled_aloe_tonic = { name = "Destilirani tonik aloje", woodCost = 1, glassCost = 2, ironCost = 1, time = 8, cost = 220, healing = 35, prestige = 4, happiness = 2, description = "Destilirani tonik aloje za notranjo uporabo." },
    silver_vial_aloe_extract = { name = "Srebrna viale ekstrakta", woodCost = 1, glassCost = 2, silverCost = 1, ironCost = 1, time = 12, cost = 580, healing = 60, prestige = 12, happiness = 4, description = "Srebrna viale ekstrakta aloje za visoke plemiče." },
    gold_trimmed_aloe_elixir = { name = "Zlatookrasni eliksir aloje", woodCost = 2, glassCost = 3, goldCost = 1, silverCost = 1, time = 16, cost = 1300, healing = 95, prestige = 22, happiness = 6, description = "Eliksir aloje v zlati viale za visoko plemstvo." },
    royal_aloe_medicine_chest = { name = "Kraljevski medicinski zaboj", woodCost = 3, glassCost = 4, goldCost = 2, silverCost = 2, jewelCost = 1, pearlCost = 1, time = 23, cost = 3300, healing = 150, prestige = 55, happiness = 12, description = "Veliki kraljevski medicinski zaboj z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    aloe_bed = { name = "Alojeva greda", cost = { gold = 180, wood = 90, stone = 60, clay = 6 }, upkeep = 4, qualityBonus = 5 },
    distillery_loft = { name = "Destilarna", cost = { gold = 720, wood = 220, stone = 220, glass = 8, iron = 4 }, upkeep = 18, qualityBonus = 18 },
    alchemical_lab = { name = "Alkemični laboratorij", cost = { gold = 2200, wood = 340, stone = 480, silver = 32, glass = 16 }, upkeep = 50, qualityBonus = 30 },
    royal_apothecary_palace = { name = "Kraljevska apoteka", cost = { gold = 9200, wood = 580, stone = 720, gold = 55, jewel = 14, glass = 30 }, upkeep = 185, qualityBonus = 55, prestigeBonus = 50 },
}
AloeCultivator.woodStock = 14; AloeCultivator.clayStock = 12; AloeCultivator.glassStock = 8; AloeCultivator.ironStock = 8; AloeCultivator.silverStock = 6; AloeCultivator.goldStock = 6; AloeCultivator.jewelStock = 4; AloeCultivator.pearlStock = 4
AloeCultivator.productStock = {}; AloeCultivator.buildings = {}; AloeCultivator.maker = nil; AloeCultivator.activeMaking = {}; AloeCultivator.totalProducts = 0; AloeCultivator.dayTimer = 0
function AloeCultivator.init() AloeCultivator.woodStock=14; AloeCultivator.clayStock=12; AloeCultivator.glassStock=8; AloeCultivator.ironStock=8; AloeCultivator.silverStock=6; AloeCultivator.goldStock=6; AloeCultivator.jewelStock=4; AloeCultivator.pearlStock=4; AloeCultivator.productStock={}; AloeCultivator.buildings={}; AloeCultivator.maker=nil; AloeCultivator.activeMaking={}; AloeCultivator.totalProducts=0; AloeCultivator.dayTimer=0; print("[AloeCultivator] Royal Aloe Cultivator System initialized (6 products, 4 buildings)") end
function AloeCultivator.hireMaker(n,s) s=s or math.random(55,90); local c=480+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; AloeCultivator.maker={name=n or ("Alojar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Alojar najet: %s (spretnost: %d)",AloeCultivator.maker.name,s),"success") end; return true end
function AloeCultivator.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function AloeCultivator.build(id) local ok,e=AloeCultivator.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(AloeCultivator.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function AloeCultivator.getQualityBonus() local b=0; for _,bd in ipairs(AloeCultivator.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function AloeCultivator.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and AloeCultivator.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.clayCost and AloeCultivator.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.glassCost and AloeCultivator.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.ironCost and AloeCultivator.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and AloeCultivator.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and AloeCultivator.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and AloeCultivator.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and AloeCultivator.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #AloeCultivator.buildings==0 then return false,"Potrebna alojeva greda" end; if not AloeCultivator.maker then return false,"Potreben alojar" end; return true end
function AloeCultivator.make(pt,qty) qty=qty or 1; local ok,e=AloeCultivator.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then AloeCultivator.woodStock=AloeCultivator.woodStock-d.woodCost*qty end; if d.clayCost then AloeCultivator.clayStock=AloeCultivator.clayStock-d.clayCost*qty end; if d.glassCost then AloeCultivator.glassStock=AloeCultivator.glassStock-d.glassCost*qty end; if d.ironCost then AloeCultivator.ironStock=AloeCultivator.ironStock-d.ironCost*qty end; if d.silverCost then AloeCultivator.silverStock=AloeCultivator.silverStock-d.silverCost*qty end; if d.goldCost then AloeCultivator.goldStock=AloeCultivator.goldStock-d.goldCost*qty end; if d.jewelCost then AloeCultivator.jewelStock=AloeCultivator.jewelStock-d.jewelCost*qty end; if d.pearlCost then AloeCultivator.pearlStock=AloeCultivator.pearlStock-d.pearlCost*qty end; local t=d.time; if AloeCultivator.maker then t=math.max(1,t-math.floor(AloeCultivator.maker.skill/13)) end; table.insert(AloeCultivator.activeMaking,{id="aloe_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,healing=d.healing or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pridelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function AloeCultivator.completeMaking(m) local q=1.0+(AloeCultivator.getQualityBonus()/100); if AloeCultivator.maker then q=q+(AloeCultivator.maker.skill/150) end; q=math.min(2.4,q); AloeCultivator.productStock[m.productType]=(AloeCultivator.productStock[m.productType] or 0)+m.quantity; AloeCultivator.totalProducts=AloeCultivator.totalProducts+m.quantity; if m.healing>0 and _G.state then _G.state.medicine=(_G.state.medicine or 0)+m.healing end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if AloeCultivator.maker then AloeCultivator.maker.itemsMade=AloeCultivator.maker.itemsMade+m.quantity; if math.random()<0.25 then AloeCultivator.maker.skill=math.min(100,AloeCultivator.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Aloja pripravljena: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"aloe.harvested",{productName=m.productName,healing=m.healing,prestige=m.prestige,happiness=m.happiness}) end end
function AloeCultivator.update(dt) if not _G.state then return end; AloeCultivator.dayTimer=AloeCultivator.dayTimer+dt; if AloeCultivator.dayTimer>=30 then AloeCultivator.dayTimer=0; for i=#AloeCultivator.activeMaking,1,-1 do local m=AloeCultivator.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then AloeCultivator.completeMaking(m); table.remove(AloeCultivator.activeMaking,i) end end; local tu=0; for _,bd in ipairs(AloeCultivator.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if AloeCultivator.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function AloeCultivator.getStats() return {woodStock=AloeCultivator.woodStock,clayStock=AloeCultivator.clayStock,glassStock=AloeCultivator.glassStock,ironStock=AloeCultivator.ironStock,silverStock=AloeCultivator.silverStock,goldStock=AloeCultivator.goldStock,jewelStock=AloeCultivator.jewelStock,pearlStock=AloeCultivator.pearlStock,productStock=AloeCultivator.productStock,numBuildings=#AloeCultivator.buildings,hasMaker=AloeCultivator.maker~=nil,makerName=AloeCultivator.maker and AloeCultivator.maker.name or "—",makerSkill=AloeCultivator.maker and AloeCultivator.maker.skill or 0,activeMaking=#AloeCultivator.activeMaking,totalProducts=AloeCultivator.totalProducts} end
return AloeCultivator
